#!/usr/bin/env python3
import pandas as pd,numpy as np,json
from pathlib import Path
from scipy.stats import norm
root=Path(__file__).resolve().parents[1];o=root/'outputs';w=root/'work';m=pd.read_csv(w/'stage6_foxp2_MVP_insomnia_region.tsv.gz',sep='\t');f=pd.read_csv(w/'stage6_foxp2_FinnGen_HFRS_region.tsv.gz',sep='\t');counts={}
def clean(d,name,idcol):
 n=len(d);d=d.copy();d['pos']=pd.to_numeric(d.base_pair_location,errors='coerce');d['ea']=d.effect_allele.astype(str).str.upper();d['oa']=d.other_allele.astype(str).str.upper();d['rs']=d[idcol].astype(str);d['pair']=d.apply(lambda r:''.join(sorted([r.ea,r.oa])),axis=1);d=d[d.pair.isin(['AC','AG','CT','GT']) & d.rs.str.fullmatch(r'rs\d+')].copy();d=d.dropna(subset=['pos']);d['pos']=d.pos.astype(int);dup=d.duplicated(['pos','rs','pair'],keep=False);counts[name]={'input':n,'valid_nonpal_snp_before_duplicates':len(d),'duplicate_rows_removed':int(dup.sum())};return d[~dup].copy()
m=clean(m,'mvp','rsid');f=clean(f,'hfrs','rs_id');x=m.merge(f,on=['pos','rs','pair'],suffixes=('_m','_f'),validate='one_to_one');counts['exact_pair_matches']=len(x)
valid=(x.odds_ratio>0)&(x.odds_ratio!=1)&(x.p_value_m>0)&(x.p_value_m<=1)&(x.standard_error_f>0)&x.effect_allele_frequency_m.between(.01,.99)&x.effect_allele_frequency_f.between(.01,.99)
x=x[valid].copy();x['anchor_effect_allele']=x.ea_m;x['anchor_other_allele']=x.oa_m;x['mvp_z_anchor']=np.sign(np.log(x.odds_ratio))*norm.isf(x.p_value_m/2);x['hfrs_beta_anchor']=x.beta*np.where(x.ea_f==x.anchor_effect_allele,1,-1);x['hfrs_z_anchor']=x.hfrs_beta_anchor/x.standard_error_f;x['mvp_n_effective']=4*x.num_cases*x.num_controls/(x.num_cases+x.num_controls);x=x[np.isfinite(x.mvp_z_anchor)&np.isfinite(x.hfrs_z_anchor)].copy();duplicate_rsid=x.rs.duplicated(keep=False);counts['ambiguous_rsid_rows_excluded']=int(duplicate_rsid.sum());x=x[~duplicate_rsid].copy();counts['usable_pairs']=len(x)

cols=['rs','pos','anchor_effect_allele','anchor_other_allele','mvp_z_anchor','p_value_m','odds_ratio','ea_m','effect_allele_frequency_m','n','num_cases','num_controls','mvp_n_effective','hfrs_beta_anchor','standard_error_f','hfrs_z_anchor','p_value_f','ea_f','effect_allele_frequency_f'];x[cols].sort_values('pos').to_csv(o/'stage6_foxp2_mvp_hfrs_exact_aligned.csv.gz',index=False,compression='gzip');(o/'stage6_foxp2_mvp_hfrs_harmonization_receipt.json').write_text(json.dumps(counts,indent=2)+'\n');print(json.dumps(counts));print('lead',x.loc[x.rs=='rs12536335',cols].to_string(index=False));print('n_eff min median max',x.mvp_n_effective.min(),x.mvp_n_effective.median(),x.mvp_n_effective.max())
